    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readBoilerC();

        bool keyLow = (digitalRead(LOCK_PIN) == LOW);
        if (keyLow)
        {
            if (!lockActive)
            {
                lockActive = true;
                lockSince = now;
