            lockActive = false;
        }
        bool locked = lockActive && (now - lockSince >= LOCK_CONFIRM_MS);

        bool fault = (tempC > FAULT_HIGH_C) || (tempC < FAULT_LOW_C);

        if (locked || fault)
        {
            setValve(false);
        }
        else if (tempC < FIRE_ON_C)
        {
            setValve(true);
        }
        else if (tempC > FIRE_OFF_C)
        {
            setValve(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
