// Cabin heater enable with comfort band.
// LM35 on A0, heater relay on D9, frost override on D2 (pull-up).

const int TEMP_PIN = A0;
const int HEAT_PIN = 9;
const int FROST_PIN = 2;
const float HEAT_ON_C = 18.0f;
const float HEAT_OFF_C = 22.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long FROST_CONFIRM_MS = 100;

bool heaterOn = false;
unsigned long lastSample = 0;
unsigned long lastStatus = 0;
float lastC = 0.0f;
bool frostStable = false;
bool frostCandidate = false;
unsigned long frostSince = 0;

float readCabinC()
{
    int mv = analogRead(TEMP_PIN) * 5000 / 1023;
    return mv / MV_PER_C;
}

void applyHeater(bool on)
{
    heaterOn = on;
    digitalWrite(HEAT_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("cabin: ");
    Serial.print(lastC, 1);
    Serial.print(" C heat=");
    Serial.println(heaterOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(HEAT_PIN, OUTPUT);
    pinMode(FROST_PIN, INPUT_PULLUP);
    applyHeater(false);
    Serial.begin(9600);
    lastSample = millis();
    lastStatus = millis();
    frostStable = (digitalRead(FROST_PIN) == LOW);
    frostCandidate = frostStable;
    frostSince = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        lastC = readCabinC();

        bool frostRaw = (digitalRead(FROST_PIN) == LOW);
        if (frostRaw != frostCandidate)
        {
            frostCandidate = frostRaw;
            frostSince = now;
        }
        if (frostCandidate != frostStable && (now - frostSince) >= FROST_CONFIRM_MS)
        {
            frostStable = frostCandidate;
        }

        if (frostStable)
        {
            applyHeater(true);
        }
        else if (lastC < HEAT_ON_C)
        {
            applyHeater(true);
        }
        else if (lastC > HEAT_OFF_C)
        {
            applyHeater(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Basement sump controller.
// Ultrasonic level proxy as linear voltage on A1, pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long CONFIRM_MS = 300;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
float levelCm = 0.0f;

bool wantPump = false;
unsigned long wantSince = 0;
bool wantValid = false;

bool silenceRaw = false;
unsigned long silenceSince = 0;
bool silenceValid = false;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void setPump(bool on)
{
    pumpOn = on;
    digitalWrite(PUMP_PIN, on ? HIGH : LOW);
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long t = millis();

    // Silence button: require LOW to hold continuously before latching.
    bool rawSilence = (digitalRead(SILENCE_PIN) == LOW);
    if (rawSilence != silenceRaw)
    {
        silenceRaw = rawSilence;
        silenceSince = t;
        silenceValid = false;
    }
    else if (silenceRaw && !silenceValid && (t - silenceSince >= CONFIRM_MS))
    {
        silenceValid = true;
        silenceLatched = true;
        setPump(false);
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            // Hysteresis: start at/above START_CM, stop at/below STOP_CM.
            bool want;
            if (pumpOn)
            {
                want = (levelCm > STOP_CM);
            }
            else
            {
                want = (levelCm >= START_CM);
            }

            // Require the requested state to hold continuously before switching.
            if (!wantValid || want != wantPump)
            {
                wantPump = want;
                wantSince = t;
                wantValid = true;
            }
            else if (want != pumpOn && (t - wantSince >= CONFIRM_MS))
            {
                setPump(want);
            }
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Walk-in cooler compressor controller (known-good build).
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float FAULT_LOW_C = 0.0f;
const float FAULT_HIGH_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 100;

bool cooling = false;
bool onPending = false;
bool offPending = false;
bool servicePending = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
unsigned long serviceSince = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (service)
        {
            if (!servicePending)
            {
                servicePending = true;
                serviceSince = now;
            }
        }
        else
        {
            servicePending = false;
        }

        bool serviceActive = servicePending && (now - serviceSince >= CONFIRM_MS);

        if (serviceActive || fault)
        {
            onPending = false;
            offPending = false;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                if (!onPending)
                {
                    onPending = true;
                    onSince = now;
                }
            }
            else
            {
                onPending = false;
            }

            if (tempC <= COOL_OFF_C)
            {
                if (!offPending)
                {
                    offPending = true;
                    offSince = now;
                }
            }
            else
            {
                offPending = false;
            }

            if (onPending && (now - onSince >= CONFIRM_MS))
            {
                setCompressor(true);
            }
            else if (offPending && (now - offSince >= CONFIRM_MS))
            {
                setCompressor(false);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Greenhouse nutrient drip pulse scheduler.
// Pulse driver on D8, pause button on D4 (pull-up).

const int DRIP_PIN = 8;
const int PAUSE_PIN = 4;
const unsigned long PERIOD_MS = 800;
const unsigned long PULSE_MS = 50;
const unsigned long LOG_MS = 1600;
const unsigned long PAUSE_DEBOUNCE_MS = 20;

unsigned long nextDue = 0;
unsigned long pulseUntil = 0;
unsigned long lastLog = 0;
unsigned long dripCount = 0;
bool pulsing = false;
bool paused = false;
bool pauseRaw = false;
bool pauseCandidate = false;
unsigned long pauseChangedAt = 0;

void dripHigh()
{
    digitalWrite(DRIP_PIN, HIGH);
}

void dripLow()
{
    digitalWrite(DRIP_PIN, LOW);
}

void startPulse(unsigned long now)
{
    pulsing = true;
    pulseUntil = now + PULSE_MS;
    dripHigh();
    dripCount++;
    Serial.println("drip");
}

void endPulse()
{
    pulsing = false;
    dripLow();
}

void printLog()
{
    Serial.print("drip n=");
    Serial.print(dripCount);
    Serial.print(" pause=");
    Serial.println(paused ? 1 : 0);
}

void updatePause(unsigned long now)
{
    bool raw = (digitalRead(PAUSE_PIN) == LOW);

    if (raw != pauseCandidate)
    {
        pauseCandidate = raw;
        pauseChangedAt = now;
    }
    else if (raw != pauseRaw && (now - pauseChangedAt) >= PAUSE_DEBOUNCE_MS)
    {
        pauseRaw = raw;
    }
}

void setup()
{
    pinMode(DRIP_PIN, OUTPUT);
    pinMode(PAUSE_PIN, INPUT_PULLUP);
    dripLow();
    Serial.begin(9600);
    nextDue = millis() + PERIOD_MS;
    lastLog = millis();
    pauseRaw = (digitalRead(PAUSE_PIN) == LOW);
    pauseCandidate = pauseRaw;
    pauseChangedAt = millis();
    paused = pauseRaw;
}

void loop()
{
    unsigned long now = millis();
    updatePause(now);
    paused = pauseRaw;

    if (pulsing && (long)(now - pulseUntil) >= 0)
    {
        endPulse();
    }

    if (paused)
    {
        if (pulsing)
        {
            endPulse();
        }
        nextDue = now + PERIOD_MS;
    }
    else if (!pulsing && (long)(now - nextDue) >= 0)
    {
        nextDue = now + PERIOD_MS;
        startPulse(now);
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        printLog();
    }
}

// Foyer wall switch: one pushbutton toggles a lamp channel.
// Button D5 to ground (pull-up), lamp driver D11, status over serial.

const int SWITCH_PIN = 5;
const int LAMP_PIN = 11;
const unsigned long STATUS_EVERY_MS = 1500;
const unsigned long SETTLE_MS = 40;

bool lampLit = false;
int previousRaw = HIGH;
int settledRaw = HIGH;
unsigned long rawChangedAt = 0;
unsigned long lastStatusAt = 0;
unsigned long pressEvents = 0;
unsigned long bootMs = 0;

void driveLamp(bool on)
{
    lampLit = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void flipLamp()
{
    driveLamp(!lampLit);
    pressEvents++;
}

bool isPressedEdge(int previous, int current)
{
    return previous == HIGH && current == LOW;
}

void reportLamp()
{
    Serial.print("foyer lamp=");
    Serial.println(lampLit ? "ON" : "OFF");
}

void setup()
{
    pinMode(SWITCH_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    driveLamp(false);
    Serial.begin(9600);
    previousRaw = digitalRead(SWITCH_PIN);
    settledRaw = previousRaw;
    rawChangedAt = millis();
    lastStatusAt = millis();
    bootMs = millis();
}

void loop()
{
    int raw = digitalRead(SWITCH_PIN);
    unsigned long now = millis();

    if (raw != previousRaw)
    {
        previousRaw = raw;
        rawChangedAt = now;
    }

    if (raw != settledRaw && (now - rawChangedAt) >= SETTLE_MS)
    {
        int oldSettled = settledRaw;
        settledRaw = raw;
        if (isPressedEdge(oldSettled, settledRaw))
        {
            flipLamp();
        }
    }

    if (now - lastStatusAt >= STATUS_EVERY_MS)
    {
        lastStatusAt = now;
        reportLamp();
    }
}

// Packaging glue-dot solenoid driver.
// Trigger on D2 (pull-up), solenoid on D8, armed LED on D11.

const int TRIG_PIN = 2;
const int SOL_PIN = 8;
const int ARMED_PIN = 11;
const unsigned long PULSE_MS = 2500;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 500;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long dots = 0;

void solHigh()
{
    digitalWrite(SOL_PIN, HIGH);
}

void solLow()
{
    digitalWrite(SOL_PIN, LOW);
}

void setArmedLed(bool on)
{
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("glue dots=");
    Serial.print(dots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(SOL_PIN, OUTPUT);
    pinMode(ARMED_PIN, OUTPUT);
    solLow();
    setArmedLed(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            dots++;
            solHigh();
            setArmedLed(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        solLow();
        setArmedLed(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Greenhouse ridge-vent controller.
// Soil-air LM35 on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 400;
const unsigned long FAULT_CONFIRM_MS = 300;

bool fanOn = false;
bool pendingValid = false;
bool pendingState = false;
unsigned long pendingSince = 0;
bool faultPending = false;
unsigned long faultSince = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long sampleCount = 0;
float tempC = 0.0f;
float tempMin = 999.0f;
float tempMax = -999.0f;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void trackTemp(float c)
{
    if (c < tempMin)
    {
        tempMin = c;
    }
    if (c > tempMax)
    {
        tempMax = c;
    }
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        sampleCount++;
        trackTemp(tempC);

        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);
        bool want;

        if (fault)
        {
            want = true;
        }
        else if (tempC >= OPEN_C)
        {
            want = true;
        }
        else if (tempC <= CLOSE_C)
        {
            want = false;
        }
        else
        {
            want = fanOn;
        }

        if (fault)
        {
            // Fail-safe: require the fault to hold before tripping.
            pendingValid = false;
            if (!faultPending)
            {
                faultPending = true;
                faultSince = now;
            }
            else if (now - faultSince >= FAULT_CONFIRM_MS)
            {
                if (!fanOn)
                {
                    setFan(true);
                }
            }
        }
        else
        {
            faultPending = false;
            if (want != fanOn)
            {
                if (!pendingValid || pendingState != want)
                {
                    pendingValid = true;
                    pendingState = want;
                    pendingSince = now;
                }
                else if (now - pendingSince >= CONFIRM_MS)
                {
                    setFan(want);
                    pendingValid = false;
                }
            }
            else
            {
                pendingValid = false;
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Shop hoist contactor with mushroom e-stop.
// E-stop on D3 (NC to ground via switch, pull-up), contactor on D5.
// Run request on D6 (pull-up).

const int ESTOP_PIN = 3;
const int CONTACTOR_PIN = 5;
const int RUN_PIN = 6;
const unsigned long SETTLE_MS = 30;
const unsigned long BEAT_MS = 1100;

int stableStop = HIGH;
int lastStop = HIGH;
unsigned long stopEdge = 0;
bool contactorOn = false;
unsigned long lastBeat = 0;
unsigned long tripCount = 0;

bool estopActive(int level)
{
    return level == LOW;
}

void setContactor(bool on)
{
    contactorOn = on;
    digitalWrite(CONTACTOR_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("hoist run=");
    Serial.print(contactorOn ? 1 : 0);
    Serial.print(" trips=");
    Serial.println(tripCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(RUN_PIN, INPUT_PULLUP);
    pinMode(CONTACTOR_PIN, OUTPUT);
    setContactor(false);
    Serial.begin(9600);
    stableStop = digitalRead(ESTOP_PIN);
    lastStop = stableStop;
    lastBeat = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(ESTOP_PIN);

    if (raw != lastStop)
    {
        stopEdge = now;
        lastStop = raw;
    }

    if ((now - stopEdge) >= SETTLE_MS && raw != stableStop)
    {
        if (estopActive(raw) && !estopActive(stableStop))
        {
            tripCount++;
        }
        stableStop = raw;
    }

    bool stopped = estopActive(stableStop);
    bool runReq = (digitalRead(RUN_PIN) == LOW);

    if (stopped)
    {
        setContactor(false);
    }
    else if (runReq)
    {
        setContactor(true);
    }
    else
    {
        setContactor(true);
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

// Tool-arm interlock: hold-to-arm then release to clear.
// Hold button on D3 (pull-up), armed lamp on D8.
// Aux confirm on D5 (pull-up) is logged only.

const int HOLD_PIN = 3;
const int ARMED_PIN = 8;
const int CONFIRM_PIN = 5;
const unsigned long ARM_MS = 500;
const unsigned long STATUS_MS = 1000;
const unsigned long DEBOUNCE_MS = 20;

bool held = false;
bool rawDown = false;
unsigned long rawSince = 0;
unsigned long downSince = 0;
bool armed = false;
bool confirmLogged = false;
unsigned long lastStatus = 0;
unsigned long armEvents = 0;

void setArmed(bool on)
{
    if (on && !armed)
    {
        armEvents++;
    }
    armed = on;
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("arm lit=");
    Serial.print(armed ? 1 : 0);
    Serial.print(" events=");
    Serial.println(armEvents);
}

void setup()
{
    pinMode(HOLD_PIN, INPUT_PULLUP);
    pinMode(CONFIRM_PIN, INPUT_PULLUP);
    pinMode(ARMED_PIN, OUTPUT);
    setArmed(false);
    Serial.begin(9600);
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    bool down = (digitalRead(HOLD_PIN) == LOW);
    bool confirm = (digitalRead(CONFIRM_PIN) == LOW);

    if (down != rawDown)
    {
        rawDown = down;
        rawSince = now;
    }

    if ((now - rawSince) >= DEBOUNCE_MS && down != held)
    {
        held = down;
        if (held)
        {
            downSince = now;
        }
    }

    if (held)
    {
        if ((now - downSince) >= ARM_MS)
        {
            setArmed(true);
        }
    }
    else
    {
        setArmed(false);
    }

    if (confirm)
    {
        if (!confirmLogged)
        {
            confirmLogged = true;
            Serial.println("arm confirm");
        }
    }
    else
    {
        confirmLogged = false;
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

