}

void injectLow()
{
    digitalWrite(INJECT_PIN, LOW);
}

void sendHb()
{
    Serial.print("inject hb shots=");
    Serial.println(shots);
}

void setup()
{
    pinMode(START_PIN, INPUT_PULLUP);
    pinMode(INJECT_PIN, OUTPUT);
