    stableReq = digitalRead(REQ_PIN);
    lastReq = stableReq;
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(REQ_PIN);

    if (raw != lastReq)
    {
        reqEdge = now;
        lastReq = raw;
    }

    if ((now - reqEdge) >= DEBOUNCE_MS && raw != stableReq)
    {
        stableReq = raw;
    }

    if (stableReq == LOW && doorClosed() && !locked)
    {
        setLock(true);
        engageCount++;
    }

    if (!doorClosed())
    {
        setLock(false);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long CONFIRM_MS = 200;
const unsigned long BOOST_CONFIRM_MS = 40;

bool fanOn = false;
bool boostLatched = false;
bool boostRaw = false;
unsigned long boostSince = 0;
bool onActive = false;
unsigned long onSince = 0;
bool offActive = false;
unsigned long offSince = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    if (on == fanOn)
    {
        return;
    }
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool boostActive = (digitalRead(BOOST_PIN) == LOW);

        // Confirm a boost press; a confirmed press latches the fan ON.
        if (boostActive)
        {
            if (!boostRaw)
            {
                boostRaw = true;
                boostSince = now;
            }
            else if (now - boostSince >= BOOST_CONFIRM_MS)
            {
                boostLatched = true;
            }
        }
        else
        {
            boostRaw = false;
        }

        if (tempC >= ON_C)
        {
            if (!onActive)
            {
                onActive = true;
                onSince = now;
            }
        }
        else
        {
            onActive = false;
        }
        if (tempC <= OFF_C)
        {
            if (!offActive)
            {
                offActive = true;
                offSince = now;
            }
        }
        else
        {
            offActive = false;
        }

        bool wantOn = fanOn;
        if (boostLatched)
        {
            wantOn = true;
        }
        else if (onActive && now - onSince >= CONFIRM_MS)
        {
            wantOn = true;
        }
        else if (offActive && now - offSince >= CONFIRM_MS)
        {
            wantOn = false;
        }

        if (wantOn != fanOn)
        {
            driveFan(wantOn);
        }

        // Release the boost latch once the temperature has fallen to OFF.
        if (boostLatched && tempC <= OFF_C)
        {
            boostLatched = false;
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

// Greenhouse mist injector timed pulse.
// Trigger on D4 (pull-up), injector on D9, ready lamp on D12.

const int TRIG_PIN = 4;
const int INJ_PIN = 9;
const int READY_PIN = 12;
const unsigned long PULSE_MS = 800;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 450;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long shots = 0;

void injHigh()
{
    digitalWrite(INJ_PIN, HIGH);
}

void injLow()
{
    digitalWrite(INJ_PIN, LOW);
}

void setReady(bool on)
{
    digitalWrite(READY_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("mist shots=");
    Serial.print(shots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(INJ_PIN, OUTPUT);
    pinMode(READY_PIN, OUTPUT);
    injLow();
    setReady(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            shots++;
            injHigh();
            setReady(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        injLow();
        setReady(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Harbor nav beacon: 500 ms on / 500 ms off on D12.
// Quiet mode switch on D3 (pull-up). Status over UART.

const int BEACON_PIN = 12;
const int QUIET_PIN = 3;
const byte HALF_MS = 500;
const unsigned long STATUS_MS = 2000;

bool lampOn = false;
unsigned long lastEdge = 0;
unsigned long lastStatus = 0;
unsigned long risingCount = 0;
bool quietHeld = false;

void setBeacon(bool on)
{
    lampOn = on;
    digitalWrite(BEACON_PIN, on ? HIGH : LOW);
}

void emitTick()
{
    Serial.println("tick");
    risingCount++;
}

void publishStatus()
{
    Serial.print("nav rises=");
    Serial.print(risingCount);
    Serial.print(" quiet=");
    Serial.println(quietHeld ? 1 : 0);
}

bool readQuiet()
{
    return digitalRead(QUIET_PIN) == LOW;
}

void setup()
{
    pinMode(BEACON_PIN, OUTPUT);
    pinMode(QUIET_PIN, INPUT_PULLUP);
    setBeacon(false);
    Serial.begin(9600);
    lastEdge = millis();
    lastStatus = millis();
}

void loop()
{
    quietHeld = readQuiet();
    unsigned long now = millis();

    if (quietHeld)
    {
        setBeacon(false);
        lastEdge = now;
    }
    else if (now - lastEdge >= HALF_MS)
    {
        lastEdge += HALF_MS;
        bool nextOn = !lampOn;
        setBeacon(nextOn);
        if (nextOn)
        {
            emitTick();
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Control-panel key: toggles a status LED for the technician.
// Key on D2 (pull-up to Vcc, closes to ground), LED on D13.

const int KEY_PIN = 2;
const int LED_PIN = 13;
const unsigned long REPORT_MS = 1000;
const unsigned long SETTLE_MS = 40;

bool ledLit = false;
int stableLevel = HIGH;
int lastRaw = HIGH;
unsigned long rawChangedMs = 0;
unsigned long lastReport = 0;
unsigned long edgeCount = 0;
unsigned long bootMs = 0;

void writeLed(bool on)
{
    ledLit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void flipLed()
{
    writeLed(!ledLit);
    edgeCount++;
}

void report()
{
    Serial.print("panel led=");
    Serial.print(ledLit ? 1 : 0);
    Serial.print(" edges=");
    Serial.println(edgeCount);
}

void setup()
{
    pinMode(KEY_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    writeLed(false);
    Serial.begin(9600);
    lastRaw = digitalRead(KEY_PIN);
    stableLevel = lastRaw;
    rawChangedMs = millis();
    lastReport = millis();
    bootMs = millis();
}

void loop()
{
    int nowLevel = digitalRead(KEY_PIN);
    unsigned long t = millis();

    if (nowLevel != lastRaw)
    {
        lastRaw = nowLevel;
        rawChangedMs = t;
    }

    if (lastRaw != stableLevel && (t - rawChangedMs) >= SETTLE_MS)
    {
        int newLevel = lastRaw;
        if (stableLevel == HIGH && newLevel == LOW)
        {
            flipLed();
        }
        stableLevel = newLevel;
    }

    if (t - lastReport >= REPORT_MS)
    {
        lastReport = t;
        report();
    }
}

// Front porch gate chime.
// Gate contact on D3 (pull-up, active LOW when open), chime coil on D10.
// Keep a UART heartbeat alive for the monitoring hub.

const uint8_t GATE_PIN = 3;
const uint8_t CHIME_PIN = 10;
const unsigned long CHIME_MS = 1800;
const unsigned long HB_MS = 300;
const unsigned long DEBOUNCE_MS = 20;

unsigned long lastHb = 0;
unsigned long openCount = 0;

bool chimeActive = false;
unsigned long chimeStart = 0;

bool rawOpen = false;
bool stableOpen = false;
unsigned long rawChangeAt = 0;

void chimeHigh()
{
    digitalWrite(CHIME_PIN, HIGH);
}

void chimeLow()
{
    digitalWrite(CHIME_PIN, LOW);
}

void startChime(unsigned long now)
{
    openCount++;
    chimeActive = true;
    chimeStart = now;
    chimeHigh();
}

void serviceChime(unsigned long now)
{
    if (chimeActive && (now - chimeStart >= CHIME_MS))
    {
        chimeActive = false;
        chimeLow();
    }
}

void sendHb()
{
    Serial.println("gate-hb");
}

bool gateOpened()
{
    return digitalRead(GATE_PIN) == LOW;
}

void setup()
{
    pinMode(GATE_PIN, INPUT_PULLUP);
    pinMode(CHIME_PIN, OUTPUT);
    chimeLow();
    Serial.begin(9600);
    lastHb = millis();
    rawOpen = gateOpened();
    stableOpen = rawOpen;
    rawChangeAt = millis();
}

void loop()
{
    unsigned long now = millis();

    bool reading = gateOpened();
    if (reading != rawOpen)
    {
        rawOpen = reading;
        rawChangeAt = now;
    }
    if (rawOpen != stableOpen && (now - rawChangeAt >= DEBOUNCE_MS))
    {
        stableOpen = rawOpen;
        if (stableOpen && !chimeActive)
        {
            startChime(now);
        }
    }

    serviceChime(now);

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        sendHb();
    }
}

// Process-skid flow monitor with low-flow alarm lamp.
// Flow transducer on A0 (2 mV per L/h), alarm lamp on D8.

const int FLOW_PIN = A0;
const int ALARM_PIN = 8;
const float LOW_FLOW_LPH = 100.0f;
const float HIGH_FLOW_LPH = 800.0f;
const unsigned long LOG_MS = 500;
const unsigned long CONFIRM_MS = 200;

bool alarmLit = false;
unsigned long lastLog = 0;
unsigned long sampleCount = 0;
float flowLph = 0.0f;
float peakLph = 0.0f;

bool pendingValid = false;
bool pendingState = false;
unsigned long pendingSince = 0;

float readFlowLph()
{
    int raw = analogRead(FLOW_PIN);
    float mv = (float)raw * 5000.0f / 1023.0f;
    return mv / 2.0f;
}

void setAlarm(bool on)
{
    alarmLit = on;
    digitalWrite(ALARM_PIN, on ? HIGH : LOW);
}

bool flowLooksLow(float flow)
{
    return flow < LOW_FLOW_LPH;
}

void notePeak(float flow)
{
    if (flow > peakLph)
    {
        peakLph = flow;
    }
}

void emitLog()
{
    Serial.print("flow: ");
    Serial.println(flowLph, 1);
}

void setup()
{
    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);
    Serial.begin(9600);
    lastLog = millis();
    peakLph = 0.0f;
}

void loop()
{
    flowLph = readFlowLph();
    sampleCount++;
    notePeak(flowLph);

    bool want = flowLooksLow(flowLph);
    unsigned long now = millis();

    if (want != alarmLit)
    {
        if (!pendingValid || pendingState != want)
        {
            pendingValid = true;
            pendingState = want;
            pendingSince = now;
        }
        else if (now - pendingSince >= CONFIRM_MS)
        {
            setAlarm(want);
            pendingValid = false;
        }
    }
    else
    {
        pendingValid = false;
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        emitLog();
    }
}

// Linear rail carriage motor enable with end-stop.
// Limit switch on D2 (pull-up to GND when hit), motor enable on D13.
// Jog button on D4 (pull-up) requests motion when clear.

const int LIMIT_PIN = 2;
const int MOTOR_PIN = 13;
const int JOG_PIN = 4;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long STATUS_MS = 900;

int stableLimit = HIGH;
int lastLimit = HIGH;
unsigned long limitEdge = 0;
bool motorEnabled = false;
unsigned long lastStatus = 0;
unsigned long hitCount = 0;

bool limitActiveRaw()
{
    return digitalRead(LIMIT_PIN) == LOW;
}

void setMotor(bool enabled)
{
    motorEnabled = enabled;
    digitalWrite(MOTOR_PIN, enabled ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("rail motor=");
    Serial.print(motorEnabled ? 1 : 0);
    Serial.print(" hits=");
    Serial.println(hitCount);
}

void setup()
{
    pinMode(LIMIT_PIN, INPUT_PULLUP);
    pinMode(JOG_PIN, INPUT_PULLUP);
    pinMode(MOTOR_PIN, OUTPUT);
    setMotor(true);
    Serial.begin(9600);
    stableLimit = digitalRead(LIMIT_PIN);
    lastLimit = stableLimit;
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(LIMIT_PIN);

    if (raw != lastLimit)
    {
        limitEdge = now;
        lastLimit = raw;
    }

    if ((now - limitEdge) >= DEBOUNCE_MS && raw != stableLimit)
    {
        stableLimit = raw;
        if (limitActiveRaw())
        {
            hitCount++;
        }
    }

    bool hit = (stableLimit == LOW);
    bool jog = (digitalRead(JOG_PIN) == LOW);

    if (hit)
    {
        setMotor(false);
    }
    else if (jog)
    {
        setMotor(true);
    }
    else
    {
        setMotor(true);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Shop bench run/stop: mushroom estop toggles the "machine armed" lamp.
// Estop contact on D6 (NC to ground via switch, pull-up), armed lamp on D9.

const uint8_t ESTOP_PIN = 6;
const uint8_t ARMED_PIN = 9;
const unsigned long BEAT_MS = 1200;
const unsigned long SETTLE_MS = 50;

bool armed = false;
uint8_t priorSample = HIGH;
uint8_t stableSample = HIGH;
uint8_t candidateSample = HIGH;
unsigned long candidateSince = 0;
unsigned long lastBeat = 0;
unsigned long pressCount = 0;
unsigned long bootMs = 0;

void writeArmed(bool level)
{
    armed = level;
    digitalWrite(ARMED_PIN, level ? HIGH : LOW);
}

void toggleArmed()
{
    writeArmed(!armed);
    pressCount++;
}

bool fallingEdge(uint8_t previous, uint8_t current)
{
    return previous == HIGH && current == LOW;
}

void heartbeat()
{
    Serial.print("shop armed=");
    Serial.print(armed ? 1 : 0);
    Serial.print(" presses=");
    Serial.println(pressCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(ARMED_PIN, OUTPUT);
    writeArmed(false);
    Serial.begin(9600);
    priorSample = digitalRead(ESTOP_PIN);
    stableSample = priorSample;
    candidateSample = priorSample;
    candidateSince = millis();
    lastBeat = millis();
    bootMs = millis();
}

void loop()
{
    uint8_t sample = digitalRead(ESTOP_PIN);
    unsigned long now = millis();

    if (sample != candidateSample)
    {
        candidateSample = sample;
        candidateSince = now;
    }
    else if (candidateSample != stableSample && now - candidateSince >= SETTLE_MS)
    {
        stableSample = candidateSample;
        if (fallingEdge(priorSample, stableSample))
        {
            toggleArmed();
        }
        priorSample = stableSample;
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

// Packaging glue-dot solenoid driver (known-good build).
// Trigger on D2 (pull-up), solenoid on D8, armed LED on D11.

const int TRIG_PIN = 2;
const int SOL_PIN = 8;
const int ARMED_PIN = 11;
const unsigned long PULSE_MS = 2500;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 500;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long dots = 0;

void solHigh()
{
    digitalWrite(SOL_PIN, HIGH);
}

void solLow()
{
    digitalWrite(SOL_PIN, LOW);
}

void setArmedLed(bool on)
{
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("glue dots=");
    Serial.print(dots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(SOL_PIN, OUTPUT);
    pinMode(ARMED_PIN, OUTPUT);
    solLow();
    setArmedLed(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        solLow();
        setArmedLed(true);
    }

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            dots++;
            solHigh();
            setArmedLed(false);
        }
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// CNC spindle tach display.
// Tach voltage on A5 (1 mV/rpm), warn lamp on D9, mute on D3.

const int TACH_PIN = A5;
const int WARN_PIN = 9;
const int MUTE_PIN = 3;
const float WARN_RPM = 2000.0f;
const float WARN_HYST_RPM = 50.0f;
const unsigned long PERIOD_MS = 1000;
const unsigned long SAMPLE_MS = 50;
const unsigned long CONFIRM_MS = 200;

unsigned long lastPrint = 0;
unsigned long lastSample = 0;
float rpm = 0.0f;
float rpmMin = 99999.0f;
float rpmMax = 0.0f;
bool warnLit = false;
bool warnCand = false;
unsigned long warnCandSince = 0;
bool muteCand = false;
unsigned long muteCandSince = 0;

float readRpm()
{
    int raw = analogRead(TACH_PIN);
    return raw * (5000.0f / 1023.0f);
}

void trackExtremes(float v)
{
    if (v < rpmMin)
    {
        rpmMin = v;
    }
    if (v > rpmMax)
    {
        rpmMax = v;
    }
}

void updateWarn(float v)
{
    unsigned long now = millis();

    bool mutedRaw = (digitalRead(MUTE_PIN) == LOW);
    if (mutedRaw != muteCand)
    {
        muteCand = mutedRaw;
        muteCandSince = now;
    }
    bool muted = muteCand;

    bool want;
    if (warnLit)
    {
        want = (v >= (WARN_RPM - WARN_HYST_RPM));
    }
    else
    {
        want = (v >= WARN_RPM);
    }
    want = want && (!muted);

    if (want != warnCand)
    {
        warnCand = want;
        warnCandSince = now;
    }
    if (warnCand != warnLit && (now - warnCandSince) >= CONFIRM_MS)
    {
        warnLit = warnCand;
    }

    digitalWrite(WARN_PIN, warnLit ? HIGH : LOW);
}

void printRpm(float v)
{
    Serial.print("RPM:");
    Serial.println(v, 0);
}

void setup()
{
    pinMode(WARN_PIN, OUTPUT);
    pinMode(MUTE_PIN, INPUT_PULLUP);
    digitalWrite(WARN_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
    lastSample = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        rpm = readRpm();
        trackExtremes(rpm);
        updateWarn(rpm);
    }

    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printRpm(rpm);
        Serial.print("spindle min=");
        Serial.print(rpmMin, 0);
        Serial.print(" max=");
        Serial.println(rpmMax, 0);
    }
}

// Safe-deposit vault lock latch.
// Request button on D2, door-closed sense on D3 (both pull-up), lock solenoid on D9.

const int REQ_PIN = 2;
const int DOOR_PIN = 3;
const int LOCK_PIN = 9;
const unsigned long DEBOUNCE_MS = 35;
const unsigned long STATUS_MS = 1000;

bool locked = false;
int stableReq = HIGH;
int lastReq = HIGH;
unsigned long reqEdge = 0;
unsigned long lastStatus = 0;
unsigned long engageCount = 0;

void setLock(bool on)
{
    locked = on;
    digitalWrite(LOCK_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("vault lock=");
    Serial.print(locked ? 1 : 0);
    Serial.print(" engages=");
    Serial.println(engageCount);
}

bool doorClosed()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void setup()
{
    pinMode(REQ_PIN, INPUT_PULLUP);
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(LOCK_PIN, OUTPUT);
    setLock(false);
    Serial.begin(9600);
    stableReq = digitalRead(REQ_PIN);
