// Walk-in cooler compressor controller.
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float MIN_VALID_C = 0.0f;
const float MAX_VALID_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 100;

bool cooling = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
bool onTiming = false;
bool offTiming = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (tempC < MIN_VALID_C) || (tempC > MAX_VALID_C);

        if (service || fault)
        {
            onTiming = false;
            offTiming = false;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                if (!onTiming)
                {
                    onTiming = true;
                    onSince = now;
                }
                offTiming = false;
            }
            else
            {
                onTiming = false;
            }

            if (tempC <= COOL_OFF_C)
            {
                if (!offTiming)
                {
                    offTiming = true;
                    offSince = now;
                }
                onTiming = false;
            }
            else
            {
                offTiming = false;
            }

            if (onTiming && (now - onSince >= CONFIRM_MS))
            {
                setCompressor(true);
            }
            else if (offTiming && (now - offSince >= CONFIRM_MS))
            {
                setCompressor(false);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Patio weather node: TMP36 logger with hold-to-freeze button.
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float MV_PER_C = 10.0f;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const float HYST_C = 0.5f;
const unsigned long PERIOD_MS = 1000;
const unsigned long LAMP_CONFIRM_MS = 100;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
bool wasFrozen = false;
bool lampOn = false;
bool lampPending = false;
bool lampPendingState = false;
unsigned long lampPendingSince = 0;
unsigned long samples = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1023.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    bool want = lampOn;
    if (lampOn)
    {
        if ((c <= HIGH_C) && (c >= LOW_C))
        {
            want = false;
        }
    }
    else
    {
        if ((c > HIGH_C + HYST_C) || (c < LOW_C - HYST_C))
        {
            want = true;
        }
    }

    unsigned long now = millis();
    if (want == lampOn)
    {
        lampPending = false;
    }
    else if (!lampPending || (lampPendingState != want))
    {
        lampPending = true;
        lampPendingState = want;
        lampPendingSince = now;
    }
    else if (now - lampPendingSince >= LAMP_CONFIRM_MS)
    {
        lampOn = want;
        lampPending = false;
    }

    digitalWrite(RANGE_PIN, lampOn ? HIGH : LOW);
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    samples++;
    freezeHeld = (digitalRead(FREEZE_PIN) == LOW);
    if (freezeHeld && !wasFrozen)
    {
        frozenC = tempC;
    }
    wasFrozen = freezeHeld;

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(report);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

// Patio weather node: TMP36 logger (known-good build).
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const float HYST_C = 1.0f;
const unsigned long PERIOD_MS = 1000;
const unsigned long LAMP_CONFIRM_MS = 300;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
bool lampOn = false;
bool lampPending = false;
unsigned long lampPendingSince = 0;
unsigned long samples = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1023.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    bool wantOn;
    if (!lampOn)
    {
        wantOn = ((c > HIGH_C) || (c < LOW_C));
    }
    else
    {
        wantOn = !((c <= (HIGH_C - HYST_C)) && (c >= (LOW_C + HYST_C)));
    }

    unsigned long now = millis();
    if (wantOn == lampOn)
    {
        lampPending = false;
    }
    else
    {
        if (!lampPending)
        {
            lampPending = true;
            lampPendingSince = now;
        }
        else if (now - lampPendingSince >= LAMP_CONFIRM_MS)
        {
            lampOn = wantOn;
            lampPending = false;
        }
    }
    digitalWrite(RANGE_PIN, lampOn ? HIGH : LOW);
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    samples++;
    freezeHeld = (digitalRead(FREEZE_PIN) == LOW);
    if (freezeHeld)
    {
        frozenC = tempC;
    }

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(tempC);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

// Compressed-air manifold pressure logger for the workshop.
// Transducer on A2: 10 mV/kPa with 500 mV zero offset. Gauge lamp on D12.

const int PRESSURE_PIN = A2;
const int GAUGE_PIN = 12;
const float WARN_KPA = 90.0f;
const float CLEAR_KPA = 89.0f;
const float ZERO_MV = 500.0f;
const float MV_PER_KPA = 10.0f;
const unsigned long SAMPLE_MS = 1000;
const unsigned long GAUGE_MS = 20;

unsigned long lastSample = 0;
unsigned long lastGauge = 0;
unsigned long readingCount = 0;
float lastKpa = 0.0f;
float minKpa = 9999.0f;
float maxKpa = 0.0f;
bool gaugeLit = false;

float readMillivolts()
{
    int raw = analogRead(PRESSURE_PIN);
    return raw * (5000.0f / 1023.0f);
}

float millivoltsToKpa(float mv)
{
    return (mv - ZERO_MV) / MV_PER_KPA;
}

void trackExtremes(float kpa)
{
    if (kpa < minKpa)
    {
        minKpa = kpa;
    }
    if (kpa > maxKpa)
    {
        maxKpa = kpa;
    }
}

void updateGauge(float kpa)
{
    if (gaugeLit)
    {
        if (kpa < CLEAR_KPA)
        {
            gaugeLit = false;
        }
    }
    else
    {
        if (kpa >= WARN_KPA)
        {
            gaugeLit = true;
        }
    }
    digitalWrite(GAUGE_PIN, gaugeLit ? HIGH : LOW);
}

void printReading()
{
    Serial.print("kPa: ");
    Serial.println(lastKpa, 1);
}

void setup()
{
    pinMode(GAUGE_PIN, OUTPUT);
    digitalWrite(GAUGE_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastGauge = lastSample;
}

void loop()
{
    unsigned long now = millis();

    if (now - lastGauge >= GAUGE_MS)
    {
        lastGauge = now;
        updateGauge(millivoltsToKpa(readMillivolts()));
    }

    if (now - lastSample < SAMPLE_MS)
    {
        return;
    }
    lastSample = now;

    float mv = readMillivolts();
    lastKpa = millivoltsToKpa(mv);
    readingCount++;
    trackExtremes(lastKpa);
    updateGauge(lastKpa);
    printReading();
}

// Yard path lamp dusk relay.
// Light sensor on A0 (mV as lux-ish units), relay on D8, manual on D3.

const int LIGHT_PIN = A0;
const int RELAY_PIN = 8;
const int MANUAL_PIN = 3;
const float ON_UNITS = 400.0f;
const float OFF_UNITS = 600.0f;
const unsigned long SAMPLE_MS = 40;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool relayOn = false;
unsigned long lastSample = 0;
unsigned long lastStatus = 0;
float lightU = 0.0f;
bool pendingOn = false;
unsigned long pendingSince = 0;

float readLightUnits()
{
    int raw = analogRead(LIGHT_PIN);
    return raw * (5000.0f / 1023.0f);
}

void setRelay(bool on)
{
    relayOn = on;
    digitalWrite(RELAY_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("yard u=");
    Serial.print(lightU, 0);
    Serial.print(" relay=");
    Serial.println(relayOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(RELAY_PIN, OUTPUT);
    pinMode(MANUAL_PIN, INPUT_PULLUP);
    setRelay(false);
    Serial.begin(9600);
    lastSample = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        lightU = readLightUnits();
        bool manual = (digitalRead(MANUAL_PIN) == LOW);

        if (manual)
        {
            setRelay(true);
            pendingOn = relayOn;
            pendingSince = now;
        }
        else
        {
            bool wantOn = relayOn;
            if (lightU < ON_UNITS)
            {
                wantOn = true;
            }
            else if (lightU > OFF_UNITS)
            {
                wantOn = false;
            }

            if (wantOn != relayOn)
            {
                if (wantOn != pendingOn)
                {
                    pendingOn = wantOn;
                    pendingSince = now;
                }
                else if (now - pendingSince >= CONFIRM_MS)
                {
                    setRelay(wantOn);
                }
            }
            else
            {
                pendingOn = relayOn;
                pendingSince = now;
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}
